function getQuestionsForSession(sessionId) {
  if (!sessionId) return TKA_DATABASE["s01"] || [];
  const normalized = sessionId.toLowerCase().replace(/[^a-z0-9]/g, "");
  let targetKey = normalized;
  if (normalized.startsWith("sesi")) {
    const num = parseInt(normalized.replace(/\D/g, "") || "1", 10);
    targetKey = "s" + (num < 10 ? "0" : "") + num;
  } else if (!targetKey.startsWith("s") && !isNaN(parseInt(targetKey, 10))) {
    const num = parseInt(targetKey, 10);
    targetKey = "s" + (num < 10 ? "0" : "") + num;
  }
  return TKA_DATABASE[targetKey] || TKA_DATABASE["s01"] || [];
}

if (typeof window !== "undefined") {
  window.TKA_DATABASE = TKA_DATABASE;
  window.getQuestionsForSession = getQuestionsForSession;
}

if (typeof module !== "undefined" && module.exports) {
  module.exports = { TKA_DATABASE, getQuestionsForSession };
}
